contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(address(this).balance >= amount);

        uint256 beforeUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeCbal = address(c).balance;

        c.addToBalance{value: 0}(); if (__ESBMC_reverted()) return;

        uint256 midUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 midCbal = address(c).balance;

        bool withdrawReverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint256 afterUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(midUserBal == beforeUserBal && midCbal == beforeCbal && !withdrawReverted);
    }

    receive() external payable {}
}

