pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUserBal = __r; } catch { return; }
        uint256 beforeCbal = address(c).balance;
        try c.addToBalance{value: 0}() {} catch { return; }
        uint256 midUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { midUserBal = __r; } catch { return; }
        uint256 midCbal = address(c).balance;
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 afterUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterUserBal = __r; } catch { return; }
        assertTrue(midUserBal == beforeUserBal && midCbal == beforeCbal && !withdrawReverted);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
